contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint v1, uint v2) public {
        // Before initialization, SetMinSum should not revert and should set MinSum to v1.
        c.SetMinSum(v1); if (__ESBMC_reverted()) return;
        uint afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        // A second SetMinSum while still uninitialized should also not revert and update MinSum to v2.
        c.SetMinSum(v2); if (__ESBMC_reverted()) return;
        uint afterSecond = c.MinSum(); if (__ESBMC_reverted()) return;

        // Mark initialized. This should not revert.
        c.Initialized(); if (__ESBMC_reverted()) return;

        // After initialization, SetMinSum must revert.
        bool revertedAfterInit;
        c.SetMinSum(v1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedAfterInit = true; } else { revertedAfterInit = false; }

        assert(afterFirst == v1 && afterSecond == v2 && revertedAfterInit);
    }
}

