pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 v1, uint256 v2) internal {
        try c.SetMinSum(v1) {} catch { return; }
        uint256 afterFirst;
        try c.MinSum() returns (uint256 __r) { afterFirst = __r; } catch { return; }
        try c.SetMinSum(v2) {} catch { return; }
        uint256 afterSecond;
        try c.MinSum() returns (uint256 __r) { afterSecond = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        bool revertedAfterInit;
        try c.SetMinSum(v1) { revertedAfterInit = false; } catch { revertedAfterInit = true; }
        assertTrue(afterFirst == v1 && afterSecond == v2 && revertedAfterInit);
    }

    function testFuzz_run(uint256 v1, uint256 v2) public {
        _run(v1, v2);
    }

    receive() external payable {}
}
